PAYLOADS = {'backend/app/backtest/orv/__init__.py': '# ORV_V1 "Orbit" — ORB-Reversal backtest module. Fence: ORV_V1_20260903\n', 'backend/app/backtest/orv/orv_v1_engine.py': '# backend/app/backtest/orv/orv_v1_engine.py\n#\n# ── ORV_V1 ENGINE ── "Orbit": ORB-Reversal signal engine on index SPOT.\n#\n# Fence: ORV_V1_20260903\n#\n# PURE functions only: no DB, no clock, no config singletons. Everything here\n# is unit-tested in test_orv_runner_sim.py and shared verbatim by any future\n# live engine — the backtest/live parity surface starts at this file.\n#\n# SPEC OF RECORD (chat, 2026-09-03), decisions D1-D1.7 locked before code,\n# amended by the two whiteboard screenshots (2026-09-03):\n#   D1    ORB = high/low of the first orb_minutes (default 90 -> 09:15-10:45)\n#         of 5m SPOT candles. The ORB must be COMPLETE (every 5m bucket\n#         present) or the day is skipped — fail-closed, counted.\n#   D2    Day filter: (ORB_high - ORB_low) must be STRICTLY GREATER than\n#         atr_pct% (default 25) of ATR(atr_period=14, daily, Wilder) computed\n#         from sessions strictly BEFORE today. No same-day leak.\n#   D3    A 5m CLOSE outside the range ARMS that side: close < ORB_low arms\n#         the BULL hunt (CE), close > ORB_high arms the BEAR hunt (PE).\n#   D1.1  Patterns (whiteboard amendment): BULL side = Hammer (long LOWER\n#         wick) or Bullish Engulfing; BEAR side = Shooting-Star shape\n#         (long UPPER wick, the "inverted hammer" drawn at a top) or\n#         Bearish Engulfing. The wick test MIRRORS per side.\n#   D1.2  Signal confirms on the pattern bar\'s CLOSE; entry is the NEXT 5m\n#         bar\'s open (= that minute\'s 1m open). No unfinished-bar reads.\n#   D1.3  Disarm: while armed, a 5m close BACK INSIDE the range before a\n#         pattern fires disarms that side. It can re-arm on a fresh close\n#         outside. Toggleable (disarm_on_reentry) so a sweep can falsify it.\n#   D1.4  If entry spot is already at-or-beyond the selected target the\n#         trade is SKIPPED (the setup\'s premise is gone). Counted.\n#   D1.5  max_trades_per_day (default 2, configurable) and\n#         max_trades_per_side (default 1). One position at a time.\n#   D1.6  SL anchor = entry SPOT +- sl_points.\n#   D1.7  Pattern search window unbounded up to entry_block_time;\n#         max_wait_bars ships INERT (0 = off) as a future sweep axis.\n#\n# ORDERING RULE (documented, tested): on each armed bar the PATTERN check\n# runs BEFORE the disarm check — a hammer that closes back inside the range\n# is still a signal (arguably the strongest one); the D1.4 target-passed\n# guard in the runner catches the degenerate case where that close already\n# sits beyond the selected target. A bar that ARMS a side is never its own\n# pattern bar (the side must have been armed BEFORE the bar).\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Tuple\n\nIST_OFFSET = 5 * 3600 + 30 * 60\nSESSION_OPEN_MIN = 9 * 60 + 15        # NSE index grid opens 09:15\n\n\n@dataclass(frozen=True)\nclass OrvBar:\n    ts: int                            # epoch seconds, bar START, IST grid\n    open: float\n    high: float\n    low: float\n    close: float\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  RESAMPLE — 1m -> tf, anchored on the 09:15 session grid\n# ─────────────────────────────────────────────────────────────────────────\ndef resample_1m(bars_1m: List[OrvBar], *, day_start_epoch: int,\n                tf_minutes: int) -> List[OrvBar]:\n    """Bucket 1m bars into tf bars anchored at 09:15 IST. A tf bar\'s ts is\n    its FIRST minute\'s ts. Bars before 09:15 are ignored. Buckets with no\n    prints are simply absent (the caller decides whether absence matters —\n    the ORB completeness gate does)."""\n    out: Dict[int, dict] = {}\n    for b in bars_1m:\n        mod = (b.ts - day_start_epoch) // 60\n        if mod < SESSION_OPEN_MIN:\n            continue\n        bucket = (mod - SESSION_OPEN_MIN) // tf_minutes\n        bts = day_start_epoch + (SESSION_OPEN_MIN + bucket * tf_minutes) * 60\n        cur = out.get(bts)\n        if cur is None:\n            out[bts] = {"o": b.open, "h": b.high, "l": b.low,\n                        "c": b.close, "last": b.ts}\n        else:\n            cur["h"] = max(cur["h"], b.high)\n            cur["l"] = min(cur["l"], b.low)\n            if b.ts > cur["last"]:\n                cur["c"], cur["last"] = b.close, b.ts\n    return [OrvBar(ts, v["o"], v["h"], v["l"], v["c"])\n            for ts, v in sorted(out.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  ORB — D1\n# ─────────────────────────────────────────────────────────────────────────\ndef compute_orb(bars_tf: List[OrvBar], *, day_start_epoch: int,\n                orb_minutes: int, tf_minutes: int\n                ) -> Optional[Tuple[float, float]]:\n    """(high, low) of the tf bars whose START lies inside the first\n    orb_minutes of the session. Returns None unless EVERY expected bucket\n    is present (fail-closed: a half-covered opening range is not a range)."""\n    need = orb_minutes // tf_minutes\n    lo_min, hi_min = SESSION_OPEN_MIN, SESSION_OPEN_MIN + orb_minutes\n    window = [b for b in bars_tf\n              if lo_min <= (b.ts - day_start_epoch) // 60 < hi_min]\n    if len(window) != need:\n        return None\n    return (max(b.high for b in window), min(b.low for b in window))\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  ATR — D2 (daily, computed by the runner over prior sessions)\n# ─────────────────────────────────────────────────────────────────────────\ndef true_ranges(daily: List[Tuple[float, float, float]]) -> List[float]:\n    """daily = [(high, low, close)] ascending. TR[0] = H-L (no prev close)."""\n    trs: List[float] = []\n    prev_c: Optional[float] = None\n    for h, l, c in daily:\n        if prev_c is None:\n            trs.append(h - l)\n        else:\n            trs.append(max(h - l, abs(h - prev_c), abs(l - prev_c)))\n        prev_c = c\n    return trs\n\n\ndef atr_series(daily: List[Tuple[float, float, float]], *, period: int,\n               method: str = "wilder") -> List[Optional[float]]:\n    """ATR value AS OF each session\'s close (index-aligned with `daily`).\n    None until `period` TRs exist. wilder = SMA seed then Wilder smoothing;\n    sma = plain rolling mean of the last `period` TRs."""\n    trs = true_ranges(daily)\n    out: List[Optional[float]] = [None] * len(trs)\n    if len(trs) < period:\n        return out\n    if method == "sma":\n        run = sum(trs[:period])\n        out[period - 1] = run / period\n        for i in range(period, len(trs)):\n            run += trs[i] - trs[i - period]\n            out[i] = run / period\n        return out\n    atr = sum(trs[:period]) / period\n    out[period - 1] = atr\n    for i in range(period, len(trs)):\n        atr = (atr * (period - 1) + trs[i]) / period\n        out[i] = atr\n    return out\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  PATTERNS — D1.1 (whiteboard definitions)\n# ─────────────────────────────────────────────────────────────────────────\ndef _parts(b: OrvBar) -> Tuple[float, float, float, float]:\n    body = abs(b.close - b.open)\n    upper = b.high - max(b.open, b.close)\n    lower = min(b.open, b.close) - b.low\n    rng = b.high - b.low\n    return body, upper, lower, rng\n\n\ndef is_hammer(b: OrvBar, *, wick_body_ratio: float = 2.0,\n              opp_wick_ratio: float = 0.5) -> bool:\n    """BULL shape: long LOWER wick, small-or-no upper wick, colour-agnostic.\n    body == 0 (doji): a dragonfly doji (upper ~ 0) qualifies, a gravestone\n    does not — the ratio tests degrade to exactly that."""\n    body, upper, lower, rng = _parts(b)\n    if rng <= 0:\n        return False\n    return lower >= wick_body_ratio * body and upper <= opp_wick_ratio * body\n\n\ndef is_shooting_star(b: OrvBar, *, wick_body_ratio: float = 2.0,\n                     opp_wick_ratio: float = 0.5) -> bool:\n    """BEAR shape (the whiteboard\'s inverted-hammer-at-a-top): long UPPER\n    wick, small-or-no lower wick, colour-agnostic. Mirror of is_hammer."""\n    body, upper, lower, rng = _parts(b)\n    if rng <= 0:\n        return False\n    return upper >= wick_body_ratio * body and lower <= opp_wick_ratio * body\n\n\ndef is_bull_engulf(prev: OrvBar, b: OrvBar, *,\n                   need_opposite_prev: bool = True) -> bool:\n    """GREEN bar whose BODY engulfs the previous bar\'s body (>= on both\n    edges). Classic form (whiteboard: red -> green) requires the previous\n    bar red; need_opposite_prev=False relaxes that for sweeps."""\n    if b.close <= b.open:\n        return False\n    if need_opposite_prev and prev.close >= prev.open:\n        return False\n    return (b.close >= max(prev.open, prev.close)\n            and b.open <= min(prev.open, prev.close))\n\n\ndef is_bear_engulf(prev: OrvBar, b: OrvBar, *,\n                   need_opposite_prev: bool = True) -> bool:\n    """RED bar whose BODY engulfs the previous bar\'s body. Mirror."""\n    if b.close >= b.open:\n        return False\n    if need_opposite_prev and prev.close <= prev.open:\n        return False\n    return (b.open >= max(prev.open, prev.close)\n            and b.close <= min(prev.open, prev.close))\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  SIGNALS — D3 + D1.1 + D1.2 + D1.3 arm/disarm state machine\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass(frozen=True)\nclass OrvSignal:\n    ts: int                            # pattern bar START ts (confirms at its close)\n    side: str                          # \'CE\' (bull reversal) | \'PE\' (bear reversal)\n    pattern: str                       # HAMMER | STAR | BULL_ENG | BEAR_ENG\n    spot_close: float                  # pattern bar close (diagnostics only)\n\n\ndef orv_signals(bars_tf: List[OrvBar], *, day_start_epoch: int,\n                orb_high: float, orb_low: float, orb_minutes: int,\n                hammer_on: bool = True, engulf_on: bool = True,\n                wick_body_ratio: float = 2.0, opp_wick_ratio: float = 0.5,\n                engulf_need_opposite_prev: bool = True,\n                disarm_on_reentry: bool = True,\n                max_wait_bars: int = 0,\n                diag: Optional[dict] = None) -> List[OrvSignal]:\n    """Walk the post-ORB tf bars and emit every raw signal in time order.\n    The RUNNER applies budgets, block time, the D1.4 target guard and the\n    one-position rule — this function states only what the chart said.\n\n    max_wait_bars (D1.7, default 0 = off): if > 0, an armed side auto-\n    disarms after that many bars without a pattern. INERT by default."""\n    d = diag if diag is not None else {}\n    for k in ("bull_arms", "bear_arms", "bull_disarms", "bear_disarms",\n              "bull_wait_disarms", "bear_wait_disarms"):\n        d.setdefault(k, 0)\n\n    orb_end_min = SESSION_OPEN_MIN + orb_minutes\n    signals: List[OrvSignal] = []\n    bull_armed = bear_armed = False\n    bull_age = bear_age = 0\n    prev: Optional[OrvBar] = None\n\n    for b in bars_tf:\n        mod = (b.ts - day_start_epoch) // 60\n        if mod < orb_end_min:\n            prev = b\n            continue\n\n        # ── D1.7 wait-window expiry FIRST: an arm older than max_wait_bars\n        # is dead BEFORE this bar\'s pattern check, so exactly max_wait_bars\n        # bars after the arming bar are pattern-eligible. Inert at 0. ──\n        if max_wait_bars > 0:\n            if bull_armed:\n                bull_age += 1\n                if bull_age > max_wait_bars:\n                    bull_armed = False\n                    d["bull_wait_disarms"] += 1\n            if bear_armed:\n                bear_age += 1\n                if bear_age > max_wait_bars:\n                    bear_armed = False\n                    d["bear_wait_disarms"] += 1\n\n        # ── pattern check next (see ORDERING RULE above) ──\n        if bull_armed:\n            pat = None\n            if hammer_on and is_hammer(b, wick_body_ratio=wick_body_ratio,\n                                       opp_wick_ratio=opp_wick_ratio):\n                pat = "HAMMER"\n            elif engulf_on and prev is not None and is_bull_engulf(\n                    prev, b, need_opposite_prev=engulf_need_opposite_prev):\n                pat = "BULL_ENG"\n            if pat is not None:\n                signals.append(OrvSignal(b.ts, "CE", pat, b.close))\n                bull_armed = False\n        if bear_armed:\n            pat = None\n            if hammer_on and is_shooting_star(\n                    b, wick_body_ratio=wick_body_ratio,\n                    opp_wick_ratio=opp_wick_ratio):\n                pat = "STAR"\n            elif engulf_on and prev is not None and is_bear_engulf(\n                    prev, b, need_opposite_prev=engulf_need_opposite_prev):\n                pat = "BEAR_ENG"\n            if pat is not None:\n                signals.append(OrvSignal(b.ts, "PE", pat, b.close))\n                bear_armed = False\n\n        # ── D1.3 disarm on close back inside ──\n        if disarm_on_reentry:\n            if bull_armed and b.close >= orb_low:\n                bull_armed = False\n                d["bull_disarms"] += 1\n            if bear_armed and b.close <= orb_high:\n                bear_armed = False\n                d["bear_disarms"] += 1\n\n        # ── D3 arm / re-arm from THIS bar\'s close (never its own pattern).\n        # NOTE: a PATTERN bar whose close is still outside the range re-arms\n        # its side here — a fresh close outside is a fresh breakout, and the\n        # runner\'s per-side budget (D1.5) is what caps re-entries. ──\n        if b.close < orb_low and not bull_armed:\n            bull_armed = True\n            bull_age = 0\n            d["bull_arms"] += 1\n        if b.close > orb_high and not bear_armed:\n            bear_armed = True\n            bear_age = 0\n            d["bear_arms"] += 1\n\n        prev = b\n\n    return signals\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  TARGETS & EXITS — D4 / D1.4 / D1.6 (pure; the runner drives the tape)\n# ─────────────────────────────────────────────────────────────────────────\ndef target_level(*, side: str, mode: str, orb_high: float, orb_low: float,\n                 entry_spot: float, custom_pts: float) -> Optional[float]:\n    """The SPOT target for a trade, or None when the entry spot already sits\n    at-or-beyond it (the D1.4 skip). CE profits UP: T1 = ORB_low,\n    T2 = ORB_high, custom = entry + pts. PE profits DOWN: T1 = ORB_high,\n    T2 = ORB_low, custom = entry - pts."""\n    if side == "CE":\n        tp = {"T1": orb_low, "T2": orb_high,\n              "custom": entry_spot + custom_pts}[mode]\n        return tp if tp > entry_spot else None\n    tp = {"T1": orb_high, "T2": orb_low,\n          "custom": entry_spot - custom_pts}[mode]\n    return tp if tp < entry_spot else None\n\n\ndef resolve_spot_exit(*, side: str, sl_level: float, tp_level: float,\n                      spot_bar: OrvBar) -> Optional[str]:\n    """Evaluate one 1m SPOT bar against the spot SL/TP of an open trade.\n    Returns \'SL\' | \'TP\' | None. Both breached inside one bar -> SL\n    (pessimistic, fleet convention). CE: SL below entry (low <= sl), TP\n    above (high >= tp). PE mirrored."""\n    if side == "CE":\n        sl_hit = spot_bar.low <= sl_level\n        tp_hit = spot_bar.high >= tp_level\n    else:\n        sl_hit = spot_bar.high >= sl_level\n        tp_hit = spot_bar.low <= tp_level\n    if sl_hit:\n        return "SL"\n    if tp_hit:\n        return "TP"\n    return None\n', 'backend/app/backtest/orv/backtest_orv_runner.py': '# backend/app/backtest/orv/backtest_orv_runner.py\n#\n# ── ORV_V1 RUNNER ── "Orbit": ORB-Reversal on NIFTY/BANKNIFTY SPOT with\n# weekly option BUY execution and SPOT-level SL/TP.\n#\n# Fence: ORV_V1_20260903\n#\n# SPEC OF RECORD (chat, 2026-09-03), D1-D1.7 in orv_v1_engine.py\'s header.\n# Runner-owned decisions:\n#   R1  Entry fill: signal confirms at the pattern 5m bar\'s close; the\n#       option fills at the NEXT minute\'s 1m OPEN (entry_min = pattern bar\n#       start + tf). entry_spot = that minute\'s SPOT 1m open. D1.2 exact.\n#   R2  Contract: nearest premium strictly BELOW premium_max (>= premium_min\n#       when set) among the EXPECTED weekly expiry, read from the 1m CLOSE\n#       of the bar ENDING at the entry minute (entry_min - 1) — the LTP a\n#       live engine sees at the fill instant. Fill at the chosen contract\'s\n#       entry-minute 1m open. No unfinished-bar reads (BRK P1/P2).\n#   R3  Exits are SPOT-level (D4/D1.6): the ladder walks 1m SPOT bars; a\n#       breached level books at the OPTION\'s own 1m CLOSE of that minute\n#       (CBO convention — a spot level has no premium print of its own).\n#       SL and TP inside one minute -> SL. EOD square-off at eod_square_off\n#       on the option 1m close. Missing option print at an exit minute =\n#       last known mark, counted stale, never a silent zero.\n#   R4  Budgets: one position at a time; max_trades_per_day (default 2);\n#       max_trades_per_side (default 1) — D1.5\'s "no re-entry after SL on\n#       the same side". Signals dropped by budget/overlap are counted, so\n#       a sweep can see what the budget is hiding.\n#   R5  ATR (D2): daily OHLC resampled ONCE from the SPOT 1m corpus over\n#       [date_from - lookback, date_to]; Wilder ATR as of each session\'s\n#       close; day d uses the value of the last session STRICTLY BEFORE d.\n#       Fewer than atr_period prior sessions -> no-trade day, counted.\n#\n# ── WHY THE DIAGNOSTICS EXIST ─────────────────────────────────────────────\n# Reversal-pattern rules are parameter-fragile and this one has FOUR gates\n# in series (ATR filter -> breakout arm -> pattern -> target guard), so a\n# "good" run can be one gate doing all the work. Every gate\'s kill count is\n# attributed, the pattern histogram shows whether one shape carries the\n# result, and eod_pnl_gross is the standing SCALP_V5 tripwire: if EOD exits\n# carry most of net, the run describes the square-off, not the reversal.\n#\n# ── PARITY NOTES ─────────────────────────────────────────────────────────\n#   P1  Selection/fill instants exactly as R1/R2 — live must sample the same.\n#   P2  Holiday awareness via app.utils.market_hours.is_trading_day.\n#   P3  ATR uses prior sessions only; the live engine reads the same series\n#       from the same daily resample. No same-day leak.\n#   P4  Fills use a contract\'s OWN 1m bars; stale marks are counted.\n#   P5  Expected weekly expiry only; an uncovered day is SKIPPED, never\n#       substituted with a farther expiry.\n\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass, field\nfrom datetime import date, datetime, timedelta\nfrom typing import Callable, Dict, List, Optional, Tuple\n\ntry:\n    from app.backtest.orv.orv_v1_engine import (\n        OrvBar, resample_1m, compute_orb, atr_series, orv_signals,\n        target_level, resolve_spot_exit, SESSION_OPEN_MIN)\nexcept ImportError:                                        # standalone tests\n    from orv_v1_engine import (  # type: ignore\n        OrvBar, resample_1m, compute_orb, atr_series, orv_signals,\n        target_level, resolve_spot_exit, SESSION_OPEN_MIN)\n\nIST_OFFSET = 5 * 3600 + 30 * 60\n\n# Index lot sizes are CONSTANTS by fleet convention (see lot_sizes.py).\nINDEX_LOTS = {"NIFTY": 65, "BANKNIFTY": 35}\n\nDEFAULTS: dict = {\n    # ── range & filter (D1, D2) ──\n    "orb_minutes": 90,\n    "timeframe_minutes": 5,\n    "atr_period": 14,\n    "atr_pct": 25.0,                   # ORB range must EXCEED this % of ATR\n    "atr_method": "wilder",            # wilder | sma\n\n    # ── patterns (D1.1) ──\n    "hammer_on": True,                 # bull: hammer / bear: shooting star\n    "engulf_on": True,                 # bull/bear engulfing\n    "wick_body_ratio": 2.0,\n    "opp_wick_ratio": 0.5,\n    "engulf_need_opposite_prev": True,\n\n    # ── state machine (D1.3, D1.7) ──\n    "disarm_on_reentry": True,\n    "max_wait_bars": 0,                # inert sweep axis (0 = off)\n\n    # ── entries & budgets (D1.5, R2, R4) ──\n    "premium_max": 180.0,              # nearest premium strictly below this\n    "premium_min": 0.0,                # optional floor; 0 = off\n    "entry_block_time": "14:30",       # no entries at-or-after this minute\n    "max_trades_per_day": 2,\n    "max_trades_per_side": 1,\n\n    # ── exits (D4, D1.4, D1.6, R3) ──\n    "target_mode": "T1",               # T1 | T2 | custom\n    "target_points": 0.0,              # custom mode: spot points from entry\n    "sl_points": 30.0,                 # spot points from entry\n    "skip_if_past_target": True,       # D1.4\n    "eod_square_off": "15:15",\n\n    # ── sizing / calendar ──\n    "lots": 1,\n    "lot_size": 0,                     # 0 = index constant\n    "skip_expiry_day": False,\n}\n\n\n@dataclass\nclass ORVTrade:\n    """Attribute surface matches BRKTrade / CBOTrade so\n    backtest_repo.persist_run works unchanged (reads t.symbol /\n    t.max_adverse / t.ambiguous_fill by ATTRIBUTE — must stay an OBJECT).\n    Deliberately NO `hedge_symbol` attribute — its presence diverts\n    persist_run to the V3/V4 hedge branch."""\n    tradingsymbol: str\n    symbol: str\n    instrument_type: str\n    strike: Optional[float]\n    expiry: Optional[str]\n    direction: str                     # always BUY\n    entry_ts: int\n    entry_price: float\n    sl: Optional[float]                # SPOT level (see condition string)\n    tp: Optional[float]                # SPOT level\n    exit_ts: Optional[int]\n    exit_price: Optional[float]\n    exit_reason: Optional[str]         # SL | TP | EOD\n    qty: int\n    condition: str\n    ambiguous_fill: bool = False\n    pnl: float = 0.0\n    charges: float = 0.0\n    net_pnl: float = 0.0\n    max_adverse: Optional[float] = None\n    max_favorable: Optional[float] = None\n    gross: float = field(default=0.0)\n    net: float = field(default=0.0)\n    ambiguous: bool = field(default=False)\n    synthetic: bool = field(default=False)\n    synth_kind: Optional[str] = field(default=None)\n\n\ndef _empty_summary() -> dict:\n    return {"total_trades": 0, "wins": 0, "losses": 0, "win_rate": 0.0,\n            "gross_pnl": 0.0, "total_charges": 0.0, "net_pnl": 0.0,\n            "max_drawdown": 0.0, "ambiguous_fills": 0}\n\n\ndef _hhmm(s: str, fallback: int) -> int:\n    """\'HH:MM\' -> minutes since midnight IST; malformed -> fallback."""\n    try:\n        h, m = str(s).split(":")\n        v = int(h) * 60 + int(m)\n        return v if 0 <= v < 24 * 60 else fallback\n    except (ValueError, AttributeError):\n        return fallback\n\n\ndef _day_start_epoch(d: date) -> int:\n    """Epoch of 00:00 IST for `d`, matching the corpus\'s day bucketing."""\n    return int((datetime(d.year, d.month, d.day)\n                - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\ndef _merge_cfg(override: Optional[dict]) -> dict:\n    cfg = dict(DEFAULTS)\n    for k, v in (override or {}).items():\n        cfg[k] = v\n    # ── normalise: a bad UI value can never silently change semantics ──\n    _tm = str(cfg.get("target_mode", "T1")).strip()\n    cfg["target_mode"] = _tm if _tm in ("T1", "T2", "custom") else "T1"\n    _am = str(cfg.get("atr_method", "wilder")).lower()\n    cfg["atr_method"] = _am if _am in ("wilder", "sma") else "wilder"\n    for k in ("orb_minutes", "timeframe_minutes", "atr_period",\n              "max_wait_bars", "max_trades_per_day", "max_trades_per_side",\n              "lots", "lot_size"):\n        try:\n            cfg[k] = max(0, int(cfg[k] or 0))\n        except (TypeError, ValueError):\n            cfg[k] = int(DEFAULTS[k])\n    cfg["lots"] = cfg["lots"] or 1\n    cfg["timeframe_minutes"] = cfg["timeframe_minutes"] or 5\n    cfg["orb_minutes"] = cfg["orb_minutes"] or 90\n    cfg["atr_period"] = cfg["atr_period"] or 14\n    cfg["max_trades_per_day"] = cfg["max_trades_per_day"] or 1\n    cfg["max_trades_per_side"] = cfg["max_trades_per_side"] or 1\n    for k in ("atr_pct", "wick_body_ratio", "opp_wick_ratio", "premium_max",\n              "premium_min", "target_points", "sl_points"):\n        try:\n            cfg[k] = abs(float(cfg[k] or 0.0))\n        except (TypeError, ValueError):\n            cfg[k] = float(DEFAULTS[k])\n    for k in ("hammer_on", "engulf_on", "engulf_need_opposite_prev",\n              "disarm_on_reentry", "skip_if_past_target", "skip_expiry_day"):\n        cfg[k] = bool(cfg.get(k, DEFAULTS[k]))\n    return cfg\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  PURE HELPERS (unit-tested in test_orv_runner_sim.py)\n# ─────────────────────────────────────────────────────────────────────────\ndef pick_candidate(prints: Dict[str, float], *, below: float,\n                   floor: float = 0.0) -> Optional[str]:\n    """R2: of {symbol: premium}, the symbol with the HIGHEST premium\n    strictly below `below` (and >= floor when floor > 0). Deterministic\n    tie-break on symbol name. Same shape as BRK\'s D1 selector."""\n    best: Optional[Tuple[float, str]] = None\n    for sym, px in prints.items():\n        if px is None or px <= 0:\n            continue\n        if px >= below:\n            continue\n        if floor > 0 and px < floor:\n            continue\n        key = (float(px), sym)\n        if best is None or key > best:\n            best = key\n    return best[1] if best else None\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  RUNNER\n# ─────────────────────────────────────────────────────────────────────────\ndef run_orv_backtest(\n    *,\n    db_path: str,\n    strategy_id: str,                  # "ORV_V1"\n    underlying: str,\n    date_from: date,\n    date_to: date,\n    config_override: Optional[dict] = None,\n    progress_cb: Optional[Callable[[dict], None]] = None,\n    cancel_cb: Optional[Callable[[], bool]] = None,\n) -> Dict:\n    try:\n        from app.event_bus.audit_logger import audit_muted\n        with audit_muted():\n            return _impl(db_path=db_path, strategy_id=strategy_id,\n                         underlying=underlying, date_from=date_from,\n                         date_to=date_to, config_override=config_override,\n                         progress_cb=progress_cb, cancel_cb=cancel_cb)\n    except ImportError:\n        return _impl(db_path=db_path, strategy_id=strategy_id,\n                     underlying=underlying, date_from=date_from,\n                     date_to=date_to, config_override=config_override,\n                     progress_cb=progress_cb, cancel_cb=cancel_cb)\n\n\ndef _abort(cfg, strategy_id, reason) -> Dict:\n    return {"run_id": None, "aborted": True, "reason": reason,\n            "trades": [], "summary": _empty_summary(),\n            "config": cfg, "strategy_id": strategy_id}\n\n\ndef _impl(*, db_path, strategy_id, underlying, date_from, date_to,\n          config_override, progress_cb, cancel_cb) -> Dict:\n    from app.backtest.data.candle_source import CandleSource\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n    from app.backtest.charges.charges_model import charges_for_long_trade\n    from app.backtest.util.lot_sizes import resolve_lot\n    from app.utils.market_hours import is_trading_day\n    from app.event_bus.audit_logger import write_audit_log\n\n    cfg = _merge_cfg(config_override)\n\n    index_lot = INDEX_LOTS.get(underlying.upper())\n    if index_lot is None:\n        return _abort(cfg, strategy_id,\n                      f"ORV_V1 is index-only; no lot constant for {underlying}.")\n    lot_size, lot_source = resolve_lot(\n        underlying=underlying, is_stock=False, cfg_lot=cfg["lot_size"],\n        index_lot=index_lot, db_path=db_path)\n    if lot_size is None:\n        return _abort(cfg, strategy_id, f"no lot size for {underlying}")\n    qty = cfg["lots"] * lot_size\n\n    tf = cfg["timeframe_minutes"]\n    orb_end_min = SESSION_OPEN_MIN + cfg["orb_minutes"]\n    block_min = _hhmm(cfg["entry_block_time"], 14 * 60 + 30)\n    eod_min = _hhmm(cfg["eod_square_off"], 15 * 60 + 15)\n    if cfg["orb_minutes"] % tf != 0:\n        return _abort(cfg, strategy_id,\n                      f"orb_minutes {cfg[\'orb_minutes\']} must be a multiple "\n                      f"of timeframe_minutes {tf}")\n    if not (orb_end_min < block_min <= eod_min):\n        return _abort(cfg, strategy_id,\n                      (f"time order must be ORB end "\n                       f"{orb_end_min // 60:02d}:{orb_end_min % 60:02d} < "\n                       f"entry_block_time {cfg[\'entry_block_time\']} <= "\n                       f"eod_square_off {cfg[\'eod_square_off\']}"))\n    if cfg["sl_points"] <= 0:\n        return _abort(cfg, strategy_id, "sl_points must be > 0")\n    if cfg["target_mode"] == "custom" and cfg["target_points"] <= 0:\n        return _abort(cfg, strategy_id,\n                      "target_mode custom needs target_points > 0")\n    if not (cfg["hammer_on"] or cfg["engulf_on"]):\n        return _abort(cfg, strategy_id,\n                      "at least one pattern family must be ON")\n    if cfg["premium_max"] <= 0:\n        return _abort(cfg, strategy_id, "premium_max must be > 0")\n\n    src = CandleSource(db_path)\n    conn = src._conn()\n\n    days: List[date] = []\n    d = date_from\n    while d <= date_to:\n        if is_trading_day(d):\n            days.append(d)\n        d += timedelta(days=1)\n\n    # ── R5: daily OHLC + ATR series, precomputed ONCE over the whole span.\n    # Lookback covers atr_period sessions with generous holiday slack.\n    lb_days = max(60, cfg["atr_period"] * 4)\n    span_lo = _day_start_epoch(date_from - timedelta(days=lb_days))\n    span_hi = _day_start_epoch(date_to) + 86400\n    daily_ohlc: Dict[date, Tuple[float, float, float, float]] = {}\n    _cur_day: Optional[date] = None\n    _o = _h = _l = _c = 0.0\n    for r in conn.execute(\n            """SELECT ts, open, high, low, close FROM backtest_candles_1m\n               WHERE underlying=? AND instrument_type=\'SPOT\'\n                 AND ts>=? AND ts<? ORDER BY ts""",\n            (underlying, span_lo, span_hi)):\n        rd = (datetime(1970, 1, 1)\n              + timedelta(seconds=r["ts"] + IST_OFFSET)).date()\n        if rd != _cur_day:\n            if _cur_day is not None:\n                daily_ohlc[_cur_day] = (_o, _h, _l, _c)\n            _cur_day, _o, _h, _l, _c = rd, r["open"], r["high"], r["low"], r["close"]\n        else:\n            _h = max(_h, r["high"])\n            _l = min(_l, r["low"])\n            _c = r["close"]\n    if _cur_day is not None:\n        daily_ohlc[_cur_day] = (_o, _h, _l, _c)\n    sessions = sorted(daily_ohlc.keys())\n    atr_vals = atr_series([(daily_ohlc[s][1], daily_ohlc[s][2],\n                            daily_ohlc[s][3]) for s in sessions],\n                          period=cfg["atr_period"], method=cfg["atr_method"])\n    atr_asof = dict(zip(sessions, atr_vals))   # value AS OF that session close\n\n    def atr_before(dd: date) -> Optional[float]:\n        """ATR as of the last session STRICTLY BEFORE dd (P3). If that\n        session\'s ATR is not yet warm this returns None — FAIL-CLOSED,\n        never a stale value from further back."""\n        import bisect\n        i = bisect.bisect_left(sessions, dd) - 1\n        if i < 0:\n            return None\n        return atr_asof.get(sessions[i])\n\n    trades: List[ORVTrade] = []\n    diag = {\n        "days_total": len(days), "days_traded": 0,\n        "days_uncovered": 0, "days_skipped_expiry": 0, "days_no_spot": 0,\n        "days_no_atr": 0, "days_orb_incomplete": 0,\n        "days_range_filter_skip": 0, "days_no_arm": 0, "days_no_signal": 0,\n        "bull_arms": 0, "bear_arms": 0, "bull_disarms": 0, "bear_disarms": 0,\n        "bull_wait_disarms": 0, "bear_wait_disarms": 0,\n        "signals_total": 0, "pattern_hist": {},\n        "sig_dropped_open": 0, "sig_dropped_budget": 0,\n        "sig_dropped_side_budget": 0, "sig_dropped_block_time": 0,\n        "sig_no_candidate": 0, "sig_no_spot_bar": 0, "sig_no_fill": 0,\n        "target_passed_skips": 0,\n        "entries": 0, "ce_entries": 0, "pe_entries": 0,\n        "entry_minute_hist": {},\n        "sl_exits": 0, "tp_exits": 0, "eod_exits": 0,\n        "sl_pnl_gross": 0.0, "tp_pnl_gross": 0.0, "eod_pnl_gross": 0.0,\n        "stale_marks": 0, "stale_spot": 0,\n        "orb_range_sum": 0.0, "orb_range_days": 0,\n        "atr_sum": 0.0, "atr_days": 0,\n        "underlying": underlying, "lot_size": lot_size,\n        "lot_source": lot_source, "qty": qty,\n        "corpus_db": str(db_path).rsplit("/", 1)[-1],\n    }\n\n    def close_trade(pos: dict, ts: int, px: float, reason: str) -> None:\n        gross = (px - pos["entry_px"]) * pos["qty"]\n        # ChargesResult exposes total_charges (NOT .total).\n        ch = charges_for_long_trade(entry_price=pos["entry_px"],\n                                    exit_price=px, qty=pos["qty"]).total_charges\n        net = gross - ch\n        t = pos["trade"]\n        t.exit_ts, t.exit_price, t.exit_reason = ts, round(px, 2), reason\n        t.pnl = t.gross = round(gross, 2)\n        t.charges = round(ch, 2)\n        t.net_pnl = t.net = round(net, 2)\n        t.max_adverse = round(pos["mae"], 2)\n        t.max_favorable = round(pos["mfe"], 2)\n        key = {"SL": "sl", "TP": "tp", "EOD": "eod"}[reason]\n        diag[f"{key}_exits"] += 1\n        diag[f"{key}_pnl_gross"] += round(net, 2)\n\n    for i, day in enumerate(days):\n        if cancel_cb and cancel_cb():\n            break\n        if progress_cb:\n            # Contract matches VET/TMA/PST/CBO/BRK: day = 1-based index,\n            # total_days = count, date = display string.\n            progress_cb({"day": i + 1, "total_days": len(days),\n                         "date": day.isoformat(), "trades": len(trades)})\n\n        ds = _day_start_epoch(day)\n        want = expected_expiry_for_day(day).isoformat()\n        if cfg["skip_expiry_day"] and date.fromisoformat(want) == day:\n            diag["days_skipped_expiry"] += 1\n            continue\n\n        # ── SPOT tape ──\n        spot_1m = [OrvBar(r["ts"], r["open"], r["high"], r["low"], r["close"])\n                   for r in conn.execute(\n                       """SELECT ts, open, high, low, close\n                          FROM backtest_candles_1m\n                          WHERE underlying=? AND instrument_type=\'SPOT\'\n                            AND ts>=? AND ts<? ORDER BY ts""",\n                       (underlying, ds, ds + 86400))]\n        if not spot_1m:\n            diag["days_no_spot"] += 1\n            continue\n        spot_by_min = {(b.ts - ds) // 60: b for b in spot_1m}\n\n        # ── D2: ATR gate (prior sessions only) ──\n        atr = atr_before(day)\n        if atr is None or atr <= 0:\n            diag["days_no_atr"] += 1\n            continue\n\n        # ── D1: ORB, fail-closed on coverage ──\n        bars_tf = resample_1m(spot_1m, day_start_epoch=ds, tf_minutes=tf)\n        orb = compute_orb(bars_tf, day_start_epoch=ds,\n                          orb_minutes=cfg["orb_minutes"], tf_minutes=tf)\n        if orb is None:\n            diag["days_orb_incomplete"] += 1\n            continue\n        orb_high, orb_low = orb\n        orb_range = orb_high - orb_low\n        diag["orb_range_sum"] += orb_range\n        diag["orb_range_days"] += 1\n        diag["atr_sum"] += atr\n        diag["atr_days"] += 1\n        if not (orb_range > (cfg["atr_pct"] / 100.0) * atr):\n            diag["days_range_filter_skip"] += 1\n            continue\n\n        # ── D3/D1.1/D1.3: raw signals ──\n        sm_diag: dict = {}\n        sigs = orv_signals(\n            bars_tf, day_start_epoch=ds, orb_high=orb_high, orb_low=orb_low,\n            orb_minutes=cfg["orb_minutes"],\n            hammer_on=cfg["hammer_on"], engulf_on=cfg["engulf_on"],\n            wick_body_ratio=cfg["wick_body_ratio"],\n            opp_wick_ratio=cfg["opp_wick_ratio"],\n            engulf_need_opposite_prev=cfg["engulf_need_opposite_prev"],\n            disarm_on_reentry=cfg["disarm_on_reentry"],\n            max_wait_bars=cfg["max_wait_bars"], diag=sm_diag)\n        for k in ("bull_arms", "bear_arms", "bull_disarms", "bear_disarms",\n                  "bull_wait_disarms", "bear_wait_disarms"):\n            diag[k] += sm_diag.get(k, 0)\n        if sm_diag.get("bull_arms", 0) + sm_diag.get("bear_arms", 0) == 0:\n            diag["days_no_arm"] += 1\n            continue\n        if not sigs:\n            diag["days_no_signal"] += 1\n            continue\n        diag["signals_total"] += len(sigs)\n\n        # ── lazily-loaded option universe (only days that get this far) ──\n        universe = src.contracts_active_on_day(underlying, ds, expiry=want)\n        if not universe:\n            # P5: no faithful contract -> skip, never substitute an expiry.\n            diag["days_uncovered"] += 1\n            continue\n        meta: Dict[str, dict] = {}\n        bars_by_sym: Dict[str, Dict[int, object]] = {}\n\n        def bars(sym: str) -> Dict[int, object]:\n            if sym not in bars_by_sym:\n                bars_by_sym[sym] = {c.ts: c for c in\n                                    src.candles_1m_for_symbol_day(sym, ds)}\n            return bars_by_sym[sym]\n\n        day_trades = 0\n        side_trades = {"CE": 0, "PE": 0}\n        open_until: Optional[int] = None   # exit minute of the open position\n        traded = False\n\n        for s in sigs:\n            diag["pattern_hist"][s.pattern] = \\\n                diag["pattern_hist"].get(s.pattern, 0) + 1\n            entry_min = (s.ts - ds) // 60 + tf     # R1: next bar\'s open\n            if open_until is not None and entry_min <= open_until:\n                diag["sig_dropped_open"] += 1\n                continue\n            if day_trades >= cfg["max_trades_per_day"]:\n                diag["sig_dropped_budget"] += 1\n                continue\n            if side_trades[s.side] >= cfg["max_trades_per_side"]:\n                diag["sig_dropped_side_budget"] += 1\n                continue\n            if entry_min >= block_min or entry_min >= eod_min:\n                diag["sig_dropped_block_time"] += 1\n                continue\n            sb = spot_by_min.get(entry_min)\n            if sb is None:\n                diag["sig_no_spot_bar"] += 1\n                continue\n            entry_spot = float(sb.open)\n\n            # ── D4/D1.4: target guard BEFORE spending a budget slot ──\n            tp_level = target_level(\n                side=s.side, mode=cfg["target_mode"], orb_high=orb_high,\n                orb_low=orb_low, entry_spot=entry_spot,\n                custom_pts=cfg["target_points"])\n            if tp_level is None:\n                if cfg["skip_if_past_target"]:\n                    diag["target_passed_skips"] += 1\n                    continue\n                # guard disabled (sweep-only): fall through to the FULL\n                # range target so the trade still has a defined exit.\n                tp_level = orb_high if s.side == "CE" else orb_low\n            sl_level = (entry_spot - cfg["sl_points"] if s.side == "CE"\n                        else entry_spot + cfg["sl_points"])\n\n            # ── R2: contract selection at the fill instant ──\n            sel_ts = ds + (entry_min - 1) * 60     # bar ENDING at entry_min\n            prints: Dict[str, float] = {}\n            for c in universe:\n                if c.get("instrument_type") != s.side:\n                    continue\n                b = bars(c["tradingsymbol"]).get(sel_ts)\n                if b is None:\n                    continue\n                prints[c["tradingsymbol"]] = float(b.close)\n                meta[c["tradingsymbol"]] = c\n            sym = pick_candidate(prints, below=cfg["premium_max"],\n                                 floor=cfg["premium_min"])\n            if sym is None:\n                diag["sig_no_candidate"] += 1\n                continue\n            fb = bars(sym).get(ds + entry_min * 60)\n            if fb is None or not fb.open:\n                diag["sig_no_fill"] += 1\n                continue\n            entry_px = float(fb.open)\n            mc = meta[sym]\n            hh = entry_min // 60\n            mm = entry_min % 60\n            t = ORVTrade(\n                tradingsymbol=sym, symbol=sym, instrument_type=s.side,\n                strike=float(mc["strike"]) if mc.get("strike") is not None else None,\n                expiry=mc.get("expiry"), direction="BUY",\n                entry_ts=ds + entry_min * 60, entry_price=round(entry_px, 2),\n                sl=round(sl_level, 2), tp=round(tp_level, 2),\n                exit_ts=None, exit_price=None, exit_reason=None, qty=qty,\n                condition=(f"ORV·{s.side}·{s.pattern}·{hh:02d}:{mm:02d}"\n                           f"·spotSL{cfg[\'sl_points\']:g}"\n                           f"·{cfg[\'target_mode\']}"))\n            trades.append(t)\n            diag["entries"] += 1\n            diag["ce_entries" if s.side == "CE" else "pe_entries"] += 1\n            hk = f"{hh:02d}:{mm:02d}"\n            diag["entry_minute_hist"][hk] = \\\n                diag["entry_minute_hist"].get(hk, 0) + 1\n            day_trades += 1\n            side_trades[s.side] += 1\n            traded = True\n\n            # ── R3: exit ladder on 1m SPOT levels, option fills ──\n            pos = {"trade": t, "entry_px": entry_px, "qty": qty,\n                   "mae": 0.0, "mfe": 0.0, "last_mark": entry_px}\n            ob = bars(sym)\n            exit_min = eod_min\n            for m in range(entry_min, eod_min + 1):\n                o = ob.get(ds + m * 60)\n                if m >= eod_min:\n                    px = float(o.close) if o is not None else pos["last_mark"]\n                    close_trade(pos, ds + m * 60, px, "EOD")\n                    exit_min = m\n                    break\n                if o is not None:\n                    pos["last_mark"] = float(o.close)\n                    pos["mae"] = min(pos["mae"],\n                                     (float(o.low) - entry_px) * qty)\n                    pos["mfe"] = max(pos["mfe"],\n                                     (float(o.high) - entry_px) * qty)\n                else:\n                    diag["stale_marks"] += 1\n                b = spot_by_min.get(m)\n                if b is None:\n                    diag["stale_spot"] += 1\n                    continue\n                ex = resolve_spot_exit(side=s.side, sl_level=sl_level,\n                                       tp_level=tp_level, spot_bar=b)\n                if ex is not None:\n                    px = (float(o.close) if o is not None\n                          else pos["last_mark"])\n                    close_trade(pos, ds + m * 60, px, ex)\n                    exit_min = m\n                    break\n            else:\n                # Ran out of the range without EOD bar (truncated tape):\n                # book at the last known mark, never leave a row open.\n                last_ts = max(ob) if ob else ds + eod_min * 60\n                close_trade(pos, last_ts, pos["last_mark"], "EOD")\n                exit_min = eod_min\n            open_until = exit_min\n\n        if traded:\n            diag["days_traded"] += 1\n\n    src.close()\n    if diag["orb_range_days"]:\n        diag["orb_range_avg"] = round(\n            diag["orb_range_sum"] / diag["orb_range_days"], 2)\n    if diag["atr_days"]:\n        diag["atr_avg"] = round(diag["atr_sum"] / diag["atr_days"], 2)\n    summary = _summarize(trades, diag)\n    write_audit_log(\n        f"[BACKTEST][{strategy_id}] {underlying} {date_from}..{date_to}: "\n        f"{summary[\'total_trades\']} trades, net {summary[\'net_pnl\']:,.0f}, "\n        f"DD {summary[\'max_drawdown\']:,.0f}, exits SL {diag[\'sl_exits\']} / "\n        f"TP {diag[\'tp_exits\']} / EOD {diag[\'eod_exits\']}, "\n        f"days rangeSkip {diag[\'days_range_filter_skip\']} / "\n        f"noArm {diag[\'days_no_arm\']} / noSig {diag[\'days_no_signal\']} / "\n        f"noATR {diag[\'days_no_atr\']} / uncovered {diag[\'days_uncovered\']}"\n    )\n    return {"run_id": str(uuid.uuid4()), "summary": summary,\n            "config": cfg, "trades": trades, "strategy_id": strategy_id}\n\n\ndef _summarize(trades: List[ORVTrade], diag: dict) -> dict:\n    closed = [t for t in trades if t.exit_price is not None]\n    if not closed:\n        s = _empty_summary()\n        s["diag_orv"] = diag\n        return s\n    eq = peak = mdd = 0.0\n    for t in sorted(closed, key=lambda x: (x.exit_ts or 0, x.entry_ts or 0)):\n        eq += t.net_pnl\n        peak = max(peak, eq)\n        mdd = max(mdd, peak - eq)\n    nets = [t.net_pnl for t in closed]\n    wins = sum(1 for n in nets if n > 0)\n    net = sum(nets)\n    if abs(net) > 1e-9:\n        for k in ("sl", "tp", "eod"):\n            diag[f"{k}_pnl_share_pct"] = round(\n                100.0 * diag[f"{k}_pnl_gross"] / net, 1)\n    return {\n        "total_trades": len(closed), "wins": wins,\n        "losses": sum(1 for n in nets if n < 0),\n        "win_rate": round(100.0 * wins / len(closed), 2),\n        "gross_pnl": round(sum(t.pnl for t in closed), 2),\n        "total_charges": round(sum(t.charges for t in closed), 2),\n        "net_pnl": round(net, 2), "max_drawdown": round(mdd, 2),\n        "ambiguous_fills": 0,\n        "diag_orv": diag,\n    }\n', 'backend/app/backtest/orv/test_orv_runner_sim.py': '# backend/app/backtest/orv/test_orv_runner_sim.py\n#\n# ── ORV_V1 SIM SUITE ── behavioural checks for the ORB-Reversal engine and\n# runner helpers. Fence: ORV_V1_20260903.\n#\n# Run standalone:  python3 test_orv_runner_sim.py\n# Every check prints PASS/FAIL; a non-zero exit means at least one failed.\n# The suite is PURE except the final integration test, which builds a tiny\n# synthetic backtest.db in a temp dir and runs the full runner through it\n# (catches SQL/wiring/dispatch regressions the pure tests cannot see).\n\nfrom __future__ import annotations\n\nimport os\nimport sys\nimport sqlite3\nimport tempfile\nfrom datetime import date, datetime, timedelta\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nfrom orv_v1_engine import (                     # noqa: E402\n    OrvBar, resample_1m, compute_orb, true_ranges, atr_series,\n    is_hammer, is_shooting_star, is_bull_engulf, is_bear_engulf,\n    orv_signals, target_level, resolve_spot_exit, SESSION_OPEN_MIN)\nfrom backtest_orv_runner import (               # noqa: E402\n    _merge_cfg, _hhmm, pick_candidate, DEFAULTS)\n\nIST = 5 * 3600 + 30 * 60\nFAILS = []\n\n\ndef check(name: str, ok: bool, note: str = "") -> None:\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}{(\'  — \' + note) if (note and not ok) else \'\'}")\n    if not ok:\n        FAILS.append(name)\n\n\ndef ds_for(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day)\n                - datetime(1970, 1, 1)).total_seconds()) - IST\n\n\nDS = ds_for(date(2026, 1, 5))          # a Monday\n\n\ndef bar(minute: int, o, h, l, c, ds: int = DS) -> OrvBar:\n    return OrvBar(ds + minute * 60, o, h, l, c)\n\n\ndef bar5(idx: int, o, h, l, c, ds: int = DS) -> OrvBar:\n    """5m bar by post-09:15 bucket index (0 = 09:15)."""\n    return OrvBar(ds + (SESSION_OPEN_MIN + idx * 5) * 60, o, h, l, c)\n\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── resample_1m ──")\nones = [bar(SESSION_OPEN_MIN + k, 100 + k, 101 + k, 99 + k, 100.5 + k)\n        for k in range(10)]\nr5 = resample_1m(ones, day_start_epoch=DS, tf_minutes=5)\ncheck("two 5m buckets from ten 1m bars", len(r5) == 2)\ncheck("bucket open = first 1m open", r5[0].open == 100)\ncheck("bucket close = last 1m close", r5[0].close == 100.5 + 4)\ncheck("bucket high = max of highs", r5[0].high == 101 + 4)\ncheck("bucket low = min of lows", r5[0].low == 99)\ncheck("bucket ts on the 09:15 grid",\n      (r5[1].ts - DS) // 60 == SESSION_OPEN_MIN + 5)\npre = resample_1m([bar(SESSION_OPEN_MIN - 3, 1, 2, 0, 1)] + ones,\n                  day_start_epoch=DS, tf_minutes=5)\ncheck("pre-09:15 prints ignored", len(pre) == 2 and pre[0].open == 100)\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── compute_orb ──")\nfull = [bar5(i, 100, 110 + i, 90 - i, 105) for i in range(18)]\norb = compute_orb(full, day_start_epoch=DS, orb_minutes=90, tf_minutes=5)\ncheck("ORB uses exactly the first 18 buckets",\n      orb == (110 + 17, 90 - 17))\nmissing = [b for b in full if (b.ts - DS) // 60 != SESSION_OPEN_MIN + 35]\ncheck("incomplete ORB (one bucket absent) -> None",\n      compute_orb(missing, day_start_epoch=DS, orb_minutes=90,\n                  tf_minutes=5) is None)\nshort = compute_orb(full[:3], day_start_epoch=DS, orb_minutes=15,\n                    tf_minutes=5)\ncheck("orb_minutes=15 needs 3 buckets", short == (112, 88))\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── ATR ──")\ndl = [(110, 90, 100), (120, 100, 115), (118, 108, 110), (140, 100, 120)]\ntrs = true_ranges(dl)\ncheck("TR[0] = H-L", trs[0] == 20)\ncheck("TR uses prev close gap", trs[1] == max(20, 20, 0) and trs[3] == 40)\nsma = atr_series(dl, period=3, method="sma")\ncheck("SMA ATR warm at index period-1",\n      sma[0] is None and sma[1] is None and abs(sma[2] - (20 + 20 + 10) / 3) < 1e-9)\ncheck("SMA ATR rolls", abs(sma[3] - (20 + 10 + 40) / 3) < 1e-9)\nwil = atr_series(dl, period=3, method="wilder")\nseed = (20 + 20 + 10) / 3\ncheck("Wilder seed = SMA", abs(wil[2] - seed) < 1e-9)\ncheck("Wilder smoothing", abs(wil[3] - (seed * 2 + 40) / 3) < 1e-9)\ncheck("insufficient history -> all None",\n      atr_series(dl[:2], period=3) == [None, None])\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── patterns ──")\nh = OrvBar(0, 100.0, 100.6, 97.0, 100.5)      # body .5, lower 3, upper .1\ncheck("hammer: long lower wick", is_hammer(h))\ncheck("hammer is not a star", not is_shooting_star(h))\ns = OrvBar(0, 100.5, 104.0, 100.4, 100.0)     # body .5, upper 3.5, lower .4\ncheck("star: long upper wick", is_shooting_star(s))\ncheck("star is not a hammer", not is_hammer(s))\nbig_up = OrvBar(0, 100.0, 100.6, 98.5, 100.5)  # lower 1.5 < 2*.5=1.0? no: 1.5>=1.0 ok, upper .1<=.25 ok\ncheck("ratio boundary: lower exactly 2x body passes",\n      is_hammer(OrvBar(0, 100.0, 100.5, 99.0, 100.5)))\ncheck("fat opposite wick fails hammer",\n      not is_hammer(OrvBar(0, 100.0, 101.0, 97.0, 100.5)))\ndragonfly = OrvBar(0, 100.0, 100.0, 97.0, 100.0)\ncheck("dragonfly doji qualifies as hammer", is_hammer(dragonfly))\ngravestone = OrvBar(0, 100.0, 103.0, 100.0, 100.0)\ncheck("gravestone doji is NOT a hammer", not is_hammer(gravestone))\ncheck("gravestone doji IS a star", is_shooting_star(gravestone))\ncheck("flat bar (zero range) never a pattern",\n      not is_hammer(OrvBar(0, 100, 100, 100, 100))\n      and not is_shooting_star(OrvBar(0, 100, 100, 100, 100)))\nprev_r = OrvBar(0, 101.0, 101.5, 99.5, 100.0)  # red body 101->100\neng_g = OrvBar(0, 99.8, 101.9, 99.6, 101.5)    # green body 99.8->101.5\ncheck("bullish engulfing (red -> green, body engulfed)",\n      is_bull_engulf(prev_r, eng_g))\ncheck("green prev blocks classic bull engulf",\n      not is_bull_engulf(OrvBar(0, 100, 101.5, 99.5, 101.0), eng_g))\ncheck("need_opposite_prev=False relaxes it",\n      is_bull_engulf(OrvBar(0, 100, 101.5, 99.5, 101.0), eng_g,\n                     need_opposite_prev=False))\ncheck("partial engulf fails",\n      not is_bull_engulf(prev_r, OrvBar(0, 100.2, 101.9, 100.0, 101.5)))\nprev_g = OrvBar(0, 100.0, 101.5, 99.8, 101.0)\neng_r = OrvBar(0, 101.2, 101.4, 99.5, 99.8)\ncheck("bearish engulfing (green -> red)", is_bear_engulf(prev_g, eng_r))\ncheck("red bar never bull-engulfs",\n      not is_bull_engulf(prev_r, OrvBar(0, 101.5, 102, 99, 99.5)))\ncheck("equal-body edge counts (>= convention)",\n      is_bull_engulf(OrvBar(0, 101.0, 101.2, 99.9, 100.0),\n                     OrvBar(0, 100.0, 101.2, 99.9, 101.0)))\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── state machine ──")\n# ORB 09:15-09:30 (3 buckets, orb_minutes=15), range 100..110.\nORB_BARS = [bar5(0, 105, 110, 100, 106), bar5(1, 106, 109, 101, 104),\n            bar5(2, 104, 108, 100.5, 103)]\nOH, OL = 110.0, 100.0\n\n\ndef run_sm(extra, **kw):\n    d = {}\n    sig = orv_signals(ORB_BARS + extra, day_start_epoch=DS, orb_high=OH,\n                      orb_low=OL, orb_minutes=15, diag=d, **kw)\n    return sig, d\n\n\n# breakout below, then hammer -> CE\nhammer5 = bar5(4, 98.6, 98.65, 95.5, 98.4)     # body .2, lower 2.9, upper .05\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0), hammer5])\ncheck("close below ORB low arms bull", d["bull_arms"] >= 1)\ncheck("hammer while bull-armed -> CE signal",\n      len(sig) == 1 and sig[0].side == "CE" and sig[0].pattern == "HAMMER")\ncheck("signal ts = pattern bar ts", sig[0].ts == hammer5.ts)\n\n# the arming bar itself is never its own pattern\narm_hammer = bar5(3, 99.2, 99.25, 96.0, 99.1)  # closes below OL AND is a hammer\nsig, d = run_sm([arm_hammer])\ncheck("arming bar cannot be its own pattern", len(sig) == 0 and d["bull_arms"] == 1)\nsig, d = run_sm([arm_hammer, bar5(4, 99.0, 99.05, 96.0, 98.9)])\ncheck("NEXT hammer after the arming hammer fires", len(sig) == 1)\n\n# disarm on close back inside\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0),      # arm bull\n                 bar5(4, 99.5, 103.0, 99.3, 102.0),  # back inside, no pattern\n                 hammer5])\ncheck("close back inside disarms bull (no signal)",\n      len(sig) == 0 and d["bull_disarms"] == 1)\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0),\n                 bar5(4, 99.5, 103.0, 99.3, 102.0),\n                 bar5(5, 102, 102.5, 97.5, 98.0),   # fresh close outside\n                 hammer5])\ncheck("re-arm after disarm works", len(sig) == 1 and d["bull_arms"] >= 2)\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0),\n                 bar5(4, 99.5, 103.0, 99.3, 102.0),\n                 hammer5], disarm_on_reentry=False)\ncheck("disarm_on_reentry=False keeps the arm", len(sig) == 1)\n\n# pattern beats disarm on the same bar (ORDERING RULE)\ninside_hammer = bar5(4, 99.5, 100.8, 96.5, 100.7)  # hammer, closes INSIDE\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0), inside_hammer])\ncheck("pattern evaluated before disarm on the same bar",\n      len(sig) == 1 and sig[0].pattern == "HAMMER")\n\n# bear side mirror\nstar5 = bar5(4, 111.4, 114.5, 111.38, 111.5)\nsig, d = run_sm([bar5(3, 108, 112, 107, 111.0), star5])\ncheck("close above ORB high arms bear", d["bear_arms"] >= 1)\ncheck("star while bear-armed -> PE signal",\n      len(sig) == 1 and sig[0].side == "PE" and sig[0].pattern == "STAR")\n\n# engulfing path + prev-bar continuity\nprev_green = bar5(4, 111.2, 112.8, 111.0, 112.5)\nbear_eng = bar5(5, 112.7, 112.9, 110.9, 111.0)\nsig, d = run_sm([bar5(3, 108, 112, 107, 111.0), prev_green, bear_eng])\ncheck("bearish engulfing fires on the bear side",\n      any(x.pattern == "BEAR_ENG" and x.side == "PE" for x in sig))\nsig, d = run_sm([bar5(3, 108, 112, 107, 111.0), prev_green, bear_eng],\n                engulf_on=False)\ncheck("engulf_on=False silences it", len(sig) == 0)\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0), hammer5], hammer_on=False)\ncheck("hammer_on=False silences the hammer", len(sig) == 0)\n\n# both sides independent in one day\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0), hammer5,\n                 bar5(6, 108, 112, 107, 111.0),\n                 OrvBar(DS + (SESSION_OPEN_MIN + 35) * 60, 111.4, 114.5, 111.38, 111.5)])\ncheck("bull then bear signals in one day",\n      [x.side for x in sig] == ["CE", "PE"])\n\n# max_wait_bars (inert default; active when > 0)\nsig, d = run_sm([bar5(3, 102, 103, 98, 99.0),\n                 bar5(4, 99, 99.5, 98.5, 99.0),\n                 bar5(5, 99, 99.5, 98.5, 99.0),\n                 OrvBar(DS + (SESSION_OPEN_MIN + 30) * 60, 98.6, 98.65, 95.5, 98.4)],\n                max_wait_bars=2)\ncheck("max_wait_bars disarms a stale arm",\n      len(sig) == 0 and d["bull_wait_disarms"] == 1)\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── targets & exits ──")\ncheck("CE T1 = ORB low", target_level(side="CE", mode="T1", orb_high=110,\n                                      orb_low=100, entry_spot=97,\n                                      custom_pts=0) == 100)\ncheck("CE T2 = ORB high", target_level(side="CE", mode="T2", orb_high=110,\n                                       orb_low=100, entry_spot=97,\n                                       custom_pts=0) == 110)\ncheck("PE T1 = ORB high", target_level(side="PE", mode="T1", orb_high=110,\n                                       orb_low=100, entry_spot=113,\n                                       custom_pts=0) == 110)\ncheck("PE T2 = ORB low", target_level(side="PE", mode="T2", orb_high=110,\n                                      orb_low=100, entry_spot=113,\n                                      custom_pts=0) == 100)\ncheck("CE custom = entry + pts", target_level(side="CE", mode="custom",\n                                              orb_high=110, orb_low=100,\n                                              entry_spot=97,\n                                              custom_pts=25) == 122)\ncheck("PE custom = entry - pts", target_level(side="PE", mode="custom",\n                                              orb_high=110, orb_low=100,\n                                              entry_spot=113,\n                                              custom_pts=25) == 88)\ncheck("D1.4: CE entry already >= T1 -> None",\n      target_level(side="CE", mode="T1", orb_high=110, orb_low=100,\n                   entry_spot=100.5, custom_pts=0) is None)\ncheck("D1.4: PE entry already <= T1 -> None",\n      target_level(side="PE", mode="T1", orb_high=110, orb_low=100,\n                   entry_spot=109.0, custom_pts=0) is None)\n\nce_sl, ce_tp = 95.0, 100.0\ncheck("CE SL on spot low touch",\n      resolve_spot_exit(side="CE", sl_level=ce_sl, tp_level=ce_tp,\n                        spot_bar=OrvBar(0, 96, 97, 94.9, 96.5)) == "SL")\ncheck("CE TP on spot high touch",\n      resolve_spot_exit(side="CE", sl_level=ce_sl, tp_level=ce_tp,\n                        spot_bar=OrvBar(0, 99, 100.2, 98.5, 99.9)) == "TP")\ncheck("both in one bar -> SL wins",\n      resolve_spot_exit(side="CE", sl_level=ce_sl, tp_level=ce_tp,\n                        spot_bar=OrvBar(0, 97, 100.5, 94.5, 98)) == "SL")\ncheck("no touch -> None",\n      resolve_spot_exit(side="CE", sl_level=ce_sl, tp_level=ce_tp,\n                        spot_bar=OrvBar(0, 97, 99, 96, 98)) is None)\ncheck("PE SL on spot high, TP on spot low",\n      resolve_spot_exit(side="PE", sl_level=115, tp_level=108,\n                        spot_bar=OrvBar(0, 112, 115.2, 111, 113)) == "SL"\n      and resolve_spot_exit(side="PE", sl_level=115, tp_level=108,\n                            spot_bar=OrvBar(0, 110, 111, 107.8, 109)) == "TP")\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── cfg & helpers ──")\nc = _merge_cfg({"target_mode": "banana", "atr_method": "x",\n                "sl_points": -20, "max_trades_per_day": 0,\n                "orb_minutes": "junk", "atr_pct": "-25"})\ncheck("bad target_mode -> T1", c["target_mode"] == "T1")\ncheck("bad atr_method -> wilder", c["atr_method"] == "wilder")\ncheck("negative sl_points -> abs", c["sl_points"] == 20)\ncheck("zero max_trades_per_day -> 1", c["max_trades_per_day"] == 1)\ncheck("junk orb_minutes -> default", c["orb_minutes"] == DEFAULTS["orb_minutes"])\ncheck("negative atr_pct -> abs", c["atr_pct"] == 25.0)\ncheck("defaults untouched by empty override",\n      _merge_cfg(None)["max_trades_per_day"] == 2)\ncheck("_hhmm parses", _hhmm("14:30", 0) == 870 and _hhmm("junk", 99) == 99)\ncheck("pick_candidate nearest-below",\n      pick_candidate({"A": 150.0, "B": 179.5, "C": 181.0}, below=180.0) == "B")\ncheck("pick_candidate floor",\n      pick_candidate({"A": 90.0, "B": 179.5}, below=180.0, floor=100.0) == "B"\n      and pick_candidate({"A": 90.0}, below=180.0, floor=100.0) is None)\ncheck("pick_candidate empty -> None", pick_candidate({}, below=180.0) is None)\n\n# ─────────────────────────────────────────────────────────────────────────\nprint("── integration: synthetic corpus end-to-end ──")\n# atr_period=3 to keep the corpus small. Sessions: 5 warmup weekdays, then\n# the trade day. Trade day script (5m spot): ORB 09:15-09:30 = 100..110,\n# breakout below at bar 3 (close 99), hammer at bar 4, entry at bar-5 open\n# 09:40 spot open 98.0, SL 98-10=88, T1=100 hit at 10:00 -> option TP.\n\n\ndef _weekdays_before(d0: date, n: int):\n    out, d = [], d0 - timedelta(days=1)\n    while len(out) < n:\n        if d.weekday() < 5:\n            out.append(d)\n        d -= timedelta(days=1)\n    return list(reversed(out))\n\n\ndef _integration() -> None:\n    trade_day = date(2026, 1, 21)              # Wed (holiday-free week)\n    warm = _weekdays_before(trade_day, 5)\n    tmp = tempfile.mkdtemp(prefix="orv_sim_")\n    dbp = os.path.join(tmp, "backtest.db")\n    cn = sqlite3.connect(dbp)\n    cn.execute("""CREATE TABLE backtest_candles_1m (\n        instrument_token INTEGER NOT NULL, ts INTEGER NOT NULL,\n        underlying TEXT NOT NULL, tradingsymbol TEXT NOT NULL,\n        instrument_type TEXT NOT NULL, strike REAL NOT NULL,\n        expiry TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL,\n        low REAL NOT NULL, close REAL NOT NULL,\n        volume INTEGER NOT NULL DEFAULT 0, oi INTEGER NOT NULL DEFAULT 0,\n        PRIMARY KEY (instrument_token, ts))""")\n\n    def put(tok, ts, sym, itype, strike, expiry, o, h, l, c):\n        cn.execute("INSERT OR REPLACE INTO backtest_candles_1m VALUES "\n                   "(?,?,?,?,?,?,?,?,?,?,?,0,0)",\n                   (tok, ts, "NIFTY", sym, itype, strike, expiry, o, h, l, c))\n\n    # warmup sessions: flat spot days, range 20 pts -> ATR(3) = 20.\n    for wd in warm:\n        wds = ds_for(wd)\n        for k in range(0, 375):\n            m = SESSION_OPEN_MIN + k\n            put(1, wds + m * 60, "NIFTY_SPOT", "SPOT", 0, "1970-01-01",\n                100.0, 110.0, 90.0, 100.0)\n\n    # trade day 5m script, written as 1m bars (each 5m bucket = 5 identical\n    # 1m bars carrying the bucket\'s OHLC shape on its first/last minute).\n    tds = ds_for(trade_day)\n    script = {\n        0: (105, 110, 100, 106),   # ORB bars: range exactly 100..110 = 10pts\n        1: (106, 109, 101, 104),   # 10 > 25% of ATR 20 = 5 -> filter passes\n        2: (104, 108, 100.5, 103),\n        3: (102, 103, 98, 99.0),   # breakout close below 100 -> arm bull\n        4: (98.9, 98.92, 95.5, 98.8),  # HAMMER (body .1, lower 3.3, upper .02)\n        5: (98.0, 98.5, 97.5, 98.2),  # entry bar: spot open 98.0\n        6: (98.2, 99.0, 98.0, 98.8),\n        7: (98.8, 99.5, 98.5, 99.2),\n        8: (99.2, 100.4, 99.0, 100.2),  # high 100.4 >= T1 100 -> TP here\n    }\n    for idx in range(0, 75):\n        o, h, l, c = script.get(idx, (100.2, 100.4, 100.0, 100.2))\n        for k in range(5):\n            m = SESSION_OPEN_MIN + idx * 5 + k\n            # spread the 5m shape: first minute opens at o, last closes at c,\n            # every minute carries the bucket\'s full high/low so the 5m\n            # resample reproduces the script exactly.\n            put(1, tds + m * 60, "NIFTY_SPOT", "SPOT", 0, "1970-01-01",\n                o if k == 0 else c, h, l, c)\n\n    # one CE and one PE, expected weekly expiry for the trade day.\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n    exp = expected_expiry_for_day(trade_day).isoformat()\n    for idx in range(0, 75):\n        for k in range(5):\n            m = SESSION_OPEN_MIN + idx * 5 + k\n            ts = tds + m * 60\n            # CE priced to move up after entry; entry minute (09:40) open 120.\n            ce_px = 120.0 + (m - (SESSION_OPEN_MIN + 25)) * 0.5\n            put(2, ts, "NIFTYTESTCE", "CE", 24000, exp,\n                ce_px, ce_px + 1, ce_px - 1, ce_px + 0.5)\n            put(3, ts, "NIFTYTESTPE", "PE", 24000, exp,\n                90.0, 91.0, 89.0, 90.5)\n    cn.commit()\n    cn.close()\n\n    from backtest_orv_runner import run_orv_backtest\n    res = run_orv_backtest(\n        db_path=dbp, strategy_id="ORV_V1", underlying="NIFTY",\n        date_from=trade_day, date_to=trade_day,\n        config_override={"orb_minutes": 15, "atr_period": 3,\n                         "atr_pct": 25.0, "sl_points": 10.0,\n                         "target_mode": "T1", "premium_max": 180.0,\n                         "entry_block_time": "14:30",\n                         "eod_square_off": "15:15"})\n    dg = res["summary"].get("diag_orv", {})\n    check("integration: not aborted", not res.get("aborted"),\n          str(res.get("reason")))\n    check("integration: exactly one trade",\n          res["summary"]["total_trades"] == 1, str(res["summary"]))\n    if res["trades"]:\n        t = res["trades"][0]\n        check("integration: CE side, HAMMER pattern",\n              t.instrument_type == "CE" and "HAMMER" in t.condition,\n              t.condition)\n        check("integration: entry at 09:40 option open",\n              (t.entry_ts - tds) // 60 == SESSION_OPEN_MIN + 25\n              and abs(t.entry_price - 120.0) < 1e-6,\n              f"min={(t.entry_ts - tds) // 60} px={t.entry_price}")\n        check("integration: TP exit at the T1 touch minute",\n              t.exit_reason == "TP"\n              and (t.exit_ts - tds) // 60 == SESSION_OPEN_MIN + 40,\n              f"{t.exit_reason} @min {(t.exit_ts - tds) // 60}")\n        check("integration: spot SL/TP recorded on the trade",\n              abs(t.sl - 88.0) < 1e-6 and abs(t.tp - 100.0) < 1e-6,\n              f"sl={t.sl} tp={t.tp}")\n    check("integration: ATR gate passed exactly once",\n          dg.get("days_range_filter_skip") == 0 and dg.get("days_no_atr") == 0,\n          str({k: dg.get(k) for k in ("days_no_atr", "days_range_filter_skip")}))\n    check("integration: arm/pattern accounting",\n          dg.get("bull_arms", 0) >= 1 and dg.get("pattern_hist", {}).get("HAMMER") == 1,\n          str(dg.get("pattern_hist")))\n\n    # ATR gate must kill the day when atr_pct is cranked up.\n    res2 = run_orv_backtest(\n        db_path=dbp, strategy_id="ORV_V1", underlying="NIFTY",\n        date_from=trade_day, date_to=trade_day,\n        config_override={"orb_minutes": 15, "atr_period": 3,\n                         "atr_pct": 60.0, "sl_points": 10.0})\n    dg2 = res2["summary"].get("diag_orv", {})\n    check("integration: atr_pct=60 filters the day out",\n          res2["summary"]["total_trades"] == 0\n          and dg2.get("days_range_filter_skip") == 1, str(dg2))\n\n\ntry:\n    import app  # noqa: F401  (only runs inside the repo\'s backend/)\n    _HAVE_APP = True\nexcept ImportError:\n    _HAVE_APP = False\n\nif _HAVE_APP:\n    _integration()\nelse:\n    print("  SKIP  integration (app package not importable — run from backend/)")\n\n# ─────────────────────────────────────────────────────────────────────────\nprint()\nif FAILS:\n    print(f"{len(FAILS)} FAILED: {FAILS}")\n    sys.exit(1)\nprint("ALL CHECKS PASSED")\n'}

